def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the stamp's 9 and collect only its connected non-background object.
    start = next(((r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == 9), None)
    if start is None:
        return out

    background = max({v for row in grid for v in row},
                     key=lambda v: sum(row.count(v) for row in grid))
    stack = [start]
    seen = {start}
    while stack:
        r, c = stack.pop()
        for rr, cc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if (0 <= rr < h and 0 <= cc < w and
                    (rr, cc) not in seen and grid[rr][cc] != background):
                seen.add((rr, cc))
                stack.append((rr, cc))

    ar, ac = start
    stamp = [(r-ar, c-ac, grid[r][c]) for r, c in seen]
    targets = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]

    for r, c in targets:
        for dr, dc, color in stamp:
            rr, cc = r+dr, c+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
